<?php if(!defined('ABSPATH'))exit;global $wpdb;
$v=ICD_Visitas_Database::table('visitas');$e=ICD_Visitas_Database::table('escolas');$m=ICD_Visitas_Database::table('mediadores');$p=ICD_Visitas_Database::table('participantes');$mun=ICD_Visitas_Database::table('municipios');$pg=ICD_Visitas_Database::table('pedagogas');$vp=ICD_Visitas_Database::table('visita_pedagogas');
$from=sanitize_text_field($_GET['icd_de']??date('Y-01-01'));$to=sanitize_text_field($_GET['icd_ate']??current_time('Y-m-d'));$school=absint($_GET['icd_escola']??0);$mid=absint($_GET['icd_mediador']??0);$pid=absint($_GET['icd_pedagoga']??0);$municipio=absint($_GET['icd_municipio']??0);$status=sanitize_key($_GET['icd_status']??'realizada');$turno=sanitize_key($_GET['icd_turno']??'');
$where=['v.data_visita BETWEEN %s AND %s'];$args=[$from,$to];$joins=" JOIN $e e ON e.id=v.escola_id LEFT JOIN $mun mu ON mu.id=e.municipio_id ";
if($status){$where[]='v.status=%s';$args[]=$status;}if($turno){$where[]='v.turno=%s';$args[]=$turno;}if($school){$where[]='v.escola_id=%d';$args[]=$school;}if($municipio){$where[]='e.municipio_id=%d';$args[]=$municipio;}if($mid){$joins.=" JOIN $p pf ON pf.visita_id=v.id ";$where[]='pf.mediador_id=%d';$args[]=$mid;}if($pid){$joins.=" JOIN $vp vpf ON vpf.visita_id=v.id ";$where[]='vpf.pedagoga_id=%d';$args[]=$pid;}
$sqlwhere=implode(' AND ',$where);$base="FROM $v v $joins WHERE $sqlwhere";
$total=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT v.id) $base",...$args));$schools=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT v.escola_id) $base",...$args));
$medCount=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT pp.mediador_id) FROM $p pp JOIN $v v ON v.id=pp.visita_id $joins WHERE $sqlwhere",...$args));
$pedCount=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(DISTINCT vpp.pedagoga_id) FROM $vp vpp JOIN $v v ON v.id=vpp.visita_id $joins WHERE $sqlwhere",...$args));
$months=$wpdb->get_results($wpdb->prepare("SELECT DATE_FORMAT(v.data_visita,'%Y-%m') mes,COUNT(DISTINCT v.id) total $base GROUP BY mes ORDER BY mes",...$args));
$rank=$wpdb->get_results($wpdb->prepare("SELECT e.id,e.nome,COUNT(DISTINCT v.id) total,MAX(v.data_visita) ultima $base GROUP BY e.id,e.nome ORDER BY total DESC,e.nome LIMIT 12",...$args));
$recent=$wpdb->get_results($wpdb->prepare("SELECT DISTINCT v.id,v.data_visita,v.turno,v.status,v.observacoes,e.nome escola,(SELECT GROUP_CONCAT(pg2.nome SEPARATOR ', ') FROM $vp vp2 JOIN $pg pg2 ON pg2.id=vp2.pedagoga_id WHERE vp2.visita_id=v.id) pedagogas,(SELECT GROUP_CONCAT(m2.nome SEPARATOR ', ') FROM $p p2 JOIN $m m2 ON m2.id=p2.mediador_id WHERE p2.visita_id=v.id) mediadores $base ORDER BY v.data_visita DESC,v.id DESC LIMIT 8",...$args));
$allSchools=$wpdb->get_results("SELECT id,nome FROM $e WHERE ativo=1 ORDER BY nome");$allMeds=$wpdb->get_results("SELECT id,nome FROM $m WHERE ativo=1 ORDER BY nome");$allPeds=$wpdb->get_results("SELECT id,nome FROM $pg WHERE ativo=1 ORDER BY nome");$allMun=$wpdb->get_results("SELECT id,nome FROM $mun WHERE ativo=1 ORDER BY nome");$max=1;foreach($months as $x)$max=max($max,(int)$x->total);
?>
<div class="icd-shell"><header class="icd-app-header"><div class="icd-brand"><img src="<?php echo esc_url(ICD_VISITAS_URL.'assets/logo.svg');?>" alt="Instituto Caminho de Davi"><div><small>Acompanhamento pedagógico</small><h2>Dashboard de visitas</h2></div></div></header>
<?php if(current_user_can('icd_visitas_view_reports')):?><div class="icd-dashboard-tools"><a class="icd-dashboard-report" href="<?php echo esc_url(add_query_arg(['de'=>$from,'ate'=>$to,'escola'=>$school,'mediador'=>$mid,'pedagoga'=>$pid],ICD_Visitas_Public::reports_url()));?>"><span class="icd-dashboard-report-icon" aria-hidden="true">▤</span><span class="icd-dashboard-report-copy"><strong>Relatórios de visitas</strong><small>Filtrar período e gerar PDF</small></span><span class="icd-dashboard-report-arrow" aria-hidden="true">›</span></a></div><?php endif;?>
<details class="icd-card icd-filter-card" id="icd-dashboard-filters"><summary>Filtros do dashboard <span>⌄</span></summary><form class="icd-front-filters" method="get"><div class="icd-two"><label>De<input type="date" name="icd_de" value="<?php echo esc_attr($from);?>"></label><label>Até<input type="date" name="icd_ate" value="<?php echo esc_attr($to);?>"></label></div><label>Município<select name="icd_municipio"><option value="0">Todos</option><?php foreach($allMun as $x)echo '<option value="'.$x->id.'" '.selected($municipio,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Escola<select name="icd_escola"><option value="0">Todas</option><?php foreach($allSchools as $x)echo '<option value="'.$x->id.'" '.selected($school,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Mediador acompanhado<select name="icd_mediador"><option value="0">Todos</option><?php foreach($allMeds as $x)echo '<option value="'.$x->id.'" '.selected($mid,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><label>Pedagoga que realizou a visita<select name="icd_pedagoga"><option value="0">Todas</option><?php foreach($allPeds as $x)echo '<option value="'.$x->id.'" '.selected($pid,$x->id,false).'>'.esc_html($x->nome).'</option>';?></select></label><div class="icd-two"><label>Status<select name="icd_status"><option value="">Todos</option><?php foreach(['realizada','programada','confirmada','nao_realizada','cancelada','reagendada'] as $st)echo '<option value="'.$st.'" '.selected($status,$st,false).'>'.esc_html(ICD_Visitas_Helpers::status_label($st)).'</option>';?></select></label><label>Turno<select name="icd_turno"><option value="">Todos</option><?php foreach(['manha','tarde','noite','integral'] as $tr)echo '<option value="'.$tr.'" '.selected($turno,$tr,false).'>'.esc_html(ICD_Visitas_Helpers::turno_label($tr)).'</option>';?></select></label></div><div class="icd-filter-actions"><button class="icd-submit" type="submit" id="icd-apply-filters">Aplicar filtros</button><a href="<?php echo esc_url(get_permalink());?>">Limpar</a></div></form></details>
<div class="icd-kpi-grid"><div class="icd-card icd-kpi"><strong><?php echo $total;?></strong><span>Visitas</span></div><div class="icd-card icd-kpi"><strong><?php echo $schools;?></strong><span>Escolas atendidas</span></div><div class="icd-card icd-kpi"><strong><?php echo $medCount;?></strong><span>Mediadores acompanhados</span></div><div class="icd-card icd-kpi"><strong><?php echo $pedCount;?></strong><span>Pedagogas em campo</span></div></div>
<section class="icd-card"><h3>Visitas por mês</h3><?php if($months):?><div class="icd-mini-chart"><?php foreach($months as $x):?><div><b><?php echo (int)$x->total;?></b><i style="height:<?php echo max(8,round(($x->total/$max)*110));?>px"></i><span><?php echo esc_html(date_i18n('M/y',strtotime($x->mes.'-01')));?></span></div><?php endforeach;?></div><?php else:?><p>Nenhuma visita para os filtros selecionados.</p><?php endif;?></section>
<section class="icd-card"><h3>Visitas por escola</h3><small class="icd-help">Toque em uma escola para abrir o calendário de visitas.</small><?php foreach($rank as $r):?><button type="button" class="icd-rank icd-front-school-calendar-open" data-school-id="<?php echo (int)$r->id;?>" data-school-name="<?php echo esc_attr($r->nome);?>"><div><b><?php echo esc_html($r->nome);?></b><small>Última no filtro: <?php echo esc_html(date_i18n('d/m/Y',strtotime($r->ultima)));?></small></div><strong><?php echo (int)$r->total;?></strong></button><?php endforeach;if(!$rank)echo '<p>Nenhum registro.</p>';?></section>
<div class="icd-front-modal" id="icd-front-school-calendar-modal" aria-hidden="true"><div class="icd-front-modal-backdrop" data-icd-front-close-modal></div><div class="icd-front-modal-dialog" role="dialog" aria-modal="true" aria-labelledby="icd-front-calendar-title"><button type="button" class="icd-front-modal-close" data-icd-front-close-modal aria-label="Fechar">×</button><div class="icd-front-calendar-head"><div><h3 id="icd-front-calendar-title">Calendário de visitas</h3><p id="icd-front-calendar-school"></p></div><div class="icd-front-calendar-nav"><button type="button" id="icd-front-calendar-prev" aria-label="Mês anterior">‹</button><strong id="icd-front-calendar-month"></strong><button type="button" id="icd-front-calendar-next" aria-label="Próximo mês">›</button></div></div><div class="icd-front-calendar-weekdays"><span>Dom</span><span>Seg</span><span>Ter</span><span>Qua</span><span>Qui</span><span>Sex</span><span>Sáb</span></div><div class="icd-front-calendar-grid" id="icd-front-calendar-grid"></div><div class="icd-front-calendar-details" id="icd-front-calendar-details"><p class="icd-empty">Toque em um dia verde para ver as visitas.</p></div></div></div>
<section class="icd-card"><h3>Visitas recentes</h3><?php foreach($recent as $r):?><article class="icd-visit-row icd-visit-summary-open" data-visit-id="<?php echo (int)$r->id;?>" role="button" tabindex="0"><div class="icd-visit-top"><b><?php echo esc_html($r->escola);?></b><span><?php echo esc_html(date_i18n('d/m/Y',strtotime($r->data_visita)));?></span></div><small><strong>Pedagoga:</strong> <?php echo esc_html($r->pedagogas?:'Não informada');?></small><small><strong>Mediadores:</strong> <?php echo esc_html($r->mediadores?:'Não informados');?></small><?php if($r->observacoes):?><p><?php echo esc_html(wp_trim_words($r->observacoes,28,'…'));?></p><?php endif;?></article><?php endforeach;if(!$recent)echo '<p>Nenhum registro.</p>';?></section>
<?php require ICD_VISITAS_DIR.'public/nav.php';?></div>

<script>document.addEventListener('DOMContentLoaded',function(){const d=document.getElementById('icd-dashboard-filters');const b=document.getElementById('icd-apply-filters');if(b&&d)b.addEventListener('click',()=>d.removeAttribute('open'));});</script>
